insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-hero-mighty-patch-original', 'Mighty Patch Original Pimple Patch', 'Hero Cosmetics', 'skincare', 'physical', 'A drug-free hydrocolloid patch (12 mm) that you stick on a pimple overnight. Hero says it absorbs gunk in about 6 hours, shrinks the look of a pimple in one use, and keeps you from picking at it. It has no acne medicine in it, so it works as a covering, not a treatment.', '$12.99 for 36 patches on herocosmetics.us', 'https://m.media-amazon.com/images/I/61p+1+md+8L._AC_SL500_.jpg', 'https://herocosmetics.us/products/mighty-patch-original', '["acne","skin","pcos","pimple patch","hydrocolloid","drug-free"]'::jsonb, '["skin-hair"]'::jsonb, '["Hero Cosmetics"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Listed with the FDA as a Class I wound dressing (occlusive dressing, product code NAD, and hydrophilic dressing, product code NAC) under Church & Dwight''s registration, per openFDA. No 510(k) clearance was found for it. It is not a drug and has no Drug Facts label.","materials":"12 mm round hydrocolloid patches, 36 per pack (also sold in 72). Hero describes them as drug-free.","recalls":"No recalls found. openFDA device recall searches for Church & Dwight and for \"Mighty Patch\" returned no patch recalls.","sideEffects":"The product page lists no warnings or side effects. In the one small trial of a similar hydrocolloid acne dressing (not this brand), no significant side effects were seen in either group.","opinionAlerts":"Contains no acne medicine. Hydrocolloid patches were studied on inflamed, red bumps; the small trial did not test blackheads, whiteheads or deep cysts. Wear time is stated as about 6 hours in one place and 6 to 8 hours in another on Hero''s page."}'::jsonb, 'Hero says Mighty Patch absorbs gunk in about 6 hours, shrinks the look of a pimple in one use, and protects it from picking and popping. It also says the patch is drug-free, derm-tested and suitable for sensitive skin. No independent study of this product was found.

The main evidence for hydrocolloid on pimples is one small pilot trial from 2006. In Taiwan, 20 people with mild to moderate acne were randomized to a hydrocolloid acne dressing (made by 3M, not Hero) or plain skin tape on inflamed bumps for 7 days, with the dressing changed every 2 days. The authors report that the hydrocolloid group had a significantly greater drop in acne severity and redness, and their inflamed bumps healed in about 3.2 days compared with 4.3 days with tape. No significant side effects were found. With only 10 people per group and one week of follow-up, the authors called it a pilot and asked for a larger study.

Regulatory status: openFDA lists Mighty Patch as a Class I wound dressing under Church & Dwight. That is a listing, not an FDA clearance or approval, and no 510(k) clearance was found.', 'Hero''s own product page shows 5,460 reviews but no numeric average rating. On Amazon the 36-count listing shows 4.6 out of 5 stars from 186,714 ratings (read 2026-10-19).', 'One 20-person, one-week pilot trial found a hydrocolloid acne dressing (not this brand) helped inflamed bumps heal faster than plain tape. No study of Mighty Patch itself was found.', 'brand', 'Product claims are sourced from Hero Cosmetics; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"ingredients":"Hero names hydrocolloid as the key ingredient and calls it medical-grade. The product page does not publish a full material list.","doctorOpinionShort":"A drug-free hydrocolloid sticker for single pimples. One 2006 pilot trial of 20 people found a similar hydrocolloid dressing (made by 3M) helped inflamed bumps heal faster than plain tape over a week. FDA-listed as a Class I wound dressing; no 510(k) clearance found. No independent study of this product was found.","doctorOpinionCitations":[{"url":"https://herocosmetics.us/products/mighty-patch-original","label":"herocosmetics.us: Mighty Patch Original, claims and directions"},{"url":"https://library.scconline.org/v057n02/1","label":"J Cosmet Sci (2006): Chao et al., randomized double-blind pilot trial of a hydrocolloid acne dressing vs skin tape","chipLabel":"Hydrocolloid pilot trial, 20 people (2006)"},{"url":"https://api.fda.gov/device/registrationlisting.json?search=proprietary_name:patch+AND+registration.name:church&limit=10","label":"openFDA: device registration and listing for Mighty Patch (Church & Dwight, Class I, codes NAD and NAC)","chipLabel":"FDA device listing"}],"whoItsFor":["People with a single red, inflamed pimple who want to cover it overnight and stop picking","People who want a drug-free option or are already using another acne medicine","Not a treatment for blackheads, whiteheads, deep cysts, or widespread acne"],"howToUse":{"intro":"Per Hero''s product page.","steps":["Cleanse your face and let it dry.","Apply a patch to the blemish.","Leave it on for about 6 to 8 hours (overnight), then peel it off."],"sourceUrl":"https://herocosmetics.us/products/mighty-patch-original","sourceLabel":"herocosmetics.us: Mighty Patch Original"},"warnings":["Contains no acne medicine (Hero describes it as drug-free). Hero''s page lists no other warnings."],"ingredientScience":[{"name":"Hydrocolloid dressing on inflamed pimples","text":"In a 2006 randomized, double-blind pilot trial at a hospital dermatology department in Taiwan, 20 people aged 11 to 35 with mild to moderate acne were split into two groups of 10. One group used a hydrocolloid acne dressing made by 3M on inflamed bumps and the other used skin tape, for 7 days. The authors report a significantly greater drop in acne severity and in redness, oiliness and dark marks with the hydrocolloid dressing, and inflamed bumps healed in about 3.2 days vs 4.3 days. No significant side effects were found. It was a small, short pilot study of a different brand''s dressing, and the authors called for a larger trial.","citations":[{"url":"https://library.scconline.org/v057n02/1","label":"J Cosmet Sci (2006): A pilot study on efficacy treatment of acne vulgaris using a new method, randomized double-blind trial with Acne Dressing (Chao et al.)"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://herocosmetics.us/products/mighty-patch-original","text":"herocosmetics.us: Mighty Patch Original customer reviews","summary":"Hero''s own product page shows 5,460 reviews; no average rating was shown."}]}},"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb),
  ('p-hero-pimple-correct', 'Pimple Correct Acne Clearing Gel Pen', 'Hero Cosmetics', 'skincare', 'physical', 'A 2% salicylic acid spot-treatment gel in a twist pen, sold as an over-the-counter acne drug. Hero says it targets early-stage pimples to help stop them getting bigger and helps prevent new ones. Apply a thin layer to clean, dry spots, starting once a day and building up to three times a day if your skin tolerates it.', '$19.99 for 10 ml (0.34 fl oz) on herocosmetics.us', 'https://m.media-amazon.com/images/I/61Le1S+bw0L._AC_SL500_.jpg', 'https://herocosmetics.us/products/pimple-correct', '["acne","skin","pcos","salicylic acid","spot treatment"]'::jsonb, '["skin-hair"]'::jsonb, '["Hero Cosmetics"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"FDA-regulated over-the-counter acne drug with a Drug Facts label (DailyMed, Church & Dwight Co., Inc.; distributed by Hero Cosmetics). Salicylic acid 0.5% to 2% is an allowed acne active ingredient under the FDA''s OTC acne rules.","materials":"Gel in a 10 ml (0.34 fl oz) twist pen with applicator.","recalls":"No recalls found. No openFDA drug recall record for Church & Dwight mentions Hero or Pimple Correct.","allergens":"Contains tea tree leaf oil and limonene. Hero says it has no added fragrance.","sideEffects":"Dryness, peeling and irritation are possible, and more likely if you use another topical acne medicine at the same time.","opinionAlerts":"Azelaic acid and niacinamide are listed as inactive ingredients, so their amounts are not given and they should not be counted as treatment doses. Hero''s FAQ says to check with a doctor before use if pregnant; the Drug Facts label itself has no pregnancy line."}'::jsonb, 'Hero calls Pimple Correct a max-strength, derm-tested spot treatment that penetrates to help stop early-stage breakouts and helps prevent new ones. No independent study of this product was found.

The active ingredient is salicylic acid at 2%, the highest strength the FDA allows in over-the-counter acne products. In the American Academy of Dermatology''s 2024 acne guidelines, topical salicylic acid gets a conditional recommendation, a weaker grade than the strong recommendations given to benzoyl peroxide and topical retinoids such as adapalene. The AAD suggests giving acne treatments 6 to 8 weeks to work.

The gel also lists azelaic acid, niacinamide and tea tree oil, but only as inactive ingredients with no amounts given, so they should not be thought of as treatment doses.', 'Hero''s own product page shows 539 reviews but no numeric average rating. On Amazon the 0.34 fl oz listing shows 4.3 out of 5 stars from 177 ratings (read 2026-10-19).', 'Salicylic acid 2% is an FDA-allowed OTC acne ingredient with a conditional recommendation in the AAD''s 2024 guidelines. No study of this product was found.', 'brand', 'Product claims are sourced from Hero Cosmetics; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"ingredients":"Active: salicylic acid 2% (acne treatment). Inactive, per the Drug Facts label: water/aqua/eau, butylene glycol, nigella sativa seed extract, isopentyldiol, sodium polyacrylate, lactic acid, hydroxyethylcellulose, melaleuca alternifolia (tea tree) leaf oil, niacinamide, polydextrose, caffeine, maltodextrin, xanthan gum, allantoin, ceratonia siliqua gum, sodium hydroxide, opuntia ficus-indica stem extract, agar, aloe barbadensis leaf juice powder, glycerin, biosaccharide gum-1, melia azadirachta leaf extract, melia azadirachta flower extract, 1,2-hexanediol, caprylyl glycol, sodium levulinate, glyceryl caprylate, tocopherol, tocopheryl acetate, coccinia indica fruit extract, disodium phosphate, polysorbate 60, ammonium acryloyldimethyltaurate/VP copolymer, gellan gum, sodium anisate, aloe barbadensis flower extract, solanum melongena fruit extract, azelaic acid, corallina officinalis extract, curcuma longa root extract, ocimum sanctum leaf extract, simmondsia chinensis seed oil, sodium phosphate, sebacic acid, limonene.","doctorOpinionShort":"A 2% salicylic acid spot gel, the top OTC strength. The AAD''s 2024 guidelines give salicylic acid a conditional (weaker) recommendation than benzoyl peroxide or adapalene. Extra ingredients like azelaic acid and niacinamide are listed as inactive, with no amounts. No independent study of this product was found.","doctorOpinionCitations":[{"url":"https://herocosmetics.us/products/pimple-correct","label":"herocosmetics.us: Pimple Correct, claims and directions"},{"url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=869afe67-edae-4778-b990-08c2313d5aad","label":"DailyMed: Hero Cosmetics Pimple Correct Drug Facts (salicylic acid 2%)","chipLabel":"Drug Facts label"},{"url":"https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=EXT_ID:38300170%20AND%20SRC:MED&resultType=core&format=json","label":"J Am Acad Dermatol (2024): Guidelines of care for the management of acne vulgaris (Reynolds et al.), abstract via Europe PMC","chipLabel":"AAD acne guidelines (2024)"}],"whoItsFor":["People with a few new, early pimples who want an OTC spot treatment","People who prefer a precise pen applicator over a full-face product","Not a substitute for a clinician visit for widespread, painful or hormonal acne that doesn''t improve"],"howToUse":{"intro":"Per the Drug Facts label and Hero''s product page.","steps":["Cleanse skin thoroughly and let it dry.","Twist the bottom of the pen to release the gel.","Apply a thin layer over the affected area. Start once a day, then go up to two or three times a day if needed.","If dryness or peeling is bothersome, cut back to once a day or every other day."],"sourceUrl":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=869afe67-edae-4778-b990-08c2313d5aad","sourceLabel":"DailyMed: Pimple Correct Drug Facts"},"warnings":["For external use only.","Skin irritation and dryness are more likely if you use another topical acne medicine at the same time. If irritation occurs, use only one topical acne medicine at a time.","Avoid contact with eyes; if contact occurs, rinse thoroughly with water.","Do not use on open or irritated skin.","Stop use and ask a doctor if irritation becomes severe.","Pregnant: check with a doctor first (per Hero''s FAQ).","Keep out of reach of children. If swallowed, get medical help or contact a Poison Control Center right away."],"ingredientScience":[{"name":"Salicylic acid 2%","text":"The FDA''s OTC acne rules allow salicylic acid at 0.5% to 2%, so this is the top over-the-counter strength. The American Academy of Dermatology''s 2024 guidelines, built on a systematic review, give topical salicylic acid a conditional recommendation, weaker than the strong recommendations for benzoyl peroxide, topical retinoids and topical antibiotics.","citations":[{"url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-D/part-333/subpart-D/section-333.310","label":"FDA (21 CFR 333.310): Acne active ingredients, salicylic acid 0.5 to 2 percent"},{"url":"https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=EXT_ID:38300170%20AND%20SRC:MED&resultType=core&format=json","label":"J Am Acad Dermatol (2024): Guidelines of care for the management of acne vulgaris, abstract via Europe PMC"}]}],"scientificCitations":[{"url":"https://www.aad.org/public/diseases/acne/DIY/types-breakouts","text":"American Academy of Dermatology: How to treat different types of acne","summary":"AAD guidance: for papules, wash twice daily with a benzoyl peroxide or salicylic acid acne wash, and give treatment 6 to 8 weeks to work. General guidance, not product-specific validation."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://herocosmetics.us/products/pimple-correct","text":"herocosmetics.us: Pimple Correct customer reviews","summary":"Hero''s own product page shows 539 reviews; no average rating was shown."}]}},"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb),
  ('p-hero-mighty-cleanser', 'Mighty Cleanser 2% Salicylic Acid Acne Face Wash', 'Hero Cosmetics', 'skincare', 'physical', 'A 2% salicylic acid face wash sold as an over-the-counter acne drug. Hero says it clears active pimples, reduces the amount and severity of acne, and helps prevent new breakouts. Use it once or twice a day, massage onto wet skin, and rinse.', '$10.99 for 150 ml (5.07 fl oz) on herocosmetics.us', 'https://m.media-amazon.com/images/I/6140V0SQHdL._AC_SL500_.jpg', 'https://herocosmetics.us/products/mighty-cleanser', '["acne","skin","pcos","cleanser","salicylic acid"]'::jsonb, '["skin-hair"]'::jsonb, '["Hero Cosmetics"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"FDA-regulated over-the-counter acne drug with a Drug Facts label (DailyMed, Church & Dwight Co., Inc.). Salicylic acid 0.5% to 2% is an allowed acne active ingredient under the FDA''s OTC acne rules.","materials":"Rinse-off face wash in a 150 ml (5.07 fl oz) tube.","recalls":"No recalls found. No openFDA drug recall record for Church & Dwight mentions Hero or Mighty Cleanser.","sideEffects":"Dryness and irritation are possible, and more likely if you use another topical acne medicine at the same time.","opinionAlerts":"Hero''s \"89% say skin feels soft\" style numbers come from a consumer self-assessment of 171 people, not a clinical trial."}'::jsonb, 'Hero says Mighty Cleanser clears active pimples, reduces the amount and severity of acne, and helps prevent new breakouts. Its other numbers (for example 89% saying skin feels soft and 88% saying it feels less oily) come from a consumer self-assessment of 171 people, which measures how skin feels, not acne counts. No independent study of this product was found.

The active ingredient is salicylic acid at 2%, the highest strength the FDA allows in over-the-counter acne products. The American Academy of Dermatology suggests washing twice a day with a benzoyl peroxide or salicylic acid acne wash for red bumps, and giving treatment 6 to 8 weeks to work. Its 2024 guidelines give topical salicylic acid a conditional recommendation, weaker than the strong recommendations for benzoyl peroxide and topical retinoids.', 'Hero''s own product page shows 83 reviews but no numeric average rating. On Amazon the 5.07 fl oz listing shows 4.7 out of 5 stars from 53 ratings (read 2026-10-19).', 'Salicylic acid 2% is an FDA-allowed OTC acne ingredient with a conditional recommendation in the AAD''s 2024 guidelines. Hero''s own data is a 171-person self-assessment of skin feel. No study of this product was found.', 'brand', 'Product claims are sourced from Hero Cosmetics; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"ingredients":"Active: salicylic acid 2% (acne treatment). Inactive, per the Drug Facts label: water, propanediol, cocamidopropylamine oxide, cocamidopropyl betaine, potassium cocoate, glycerin, polyacrylate crosspolymer-6, sodium PCA, polyepsilon-lysine, 1,2-hexanediol, styrene/acrylates copolymer, coco-glucoside, caprylhydroxamic acid, trisodium ethylenediamine disuccinate, sodium benzoate, benzoic acid, citric acid, sodium hydroxide, sodium chloride.","doctorOpinionShort":"A 2% salicylic acid acne face wash, the top OTC strength. The AAD lists salicylic acid washes as an option for red bumps but gives salicylic acid a weaker (conditional) recommendation than benzoyl peroxide or adapalene. Hero''s percentages come from a 171-person self-assessment of how skin feels. No independent study of this product was found.","doctorOpinionCitations":[{"url":"https://herocosmetics.us/products/mighty-cleanser","label":"herocosmetics.us: Mighty Cleanser, claims and consumer self-assessment"},{"url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5597df54-2e58-0d6a-e063-6394a90a1697","label":"DailyMed: Hero Mighty Cleanser Drug Facts (salicylic acid 2%)","chipLabel":"Drug Facts label"},{"url":"https://www.aad.org/public/diseases/acne/DIY/types-breakouts","label":"American Academy of Dermatology: How to treat different types of acne"}],"whoItsFor":["People with mild acne or oily, breakout-prone skin who want an OTC acne face wash","Not a substitute for a clinician visit for widespread, painful or hormonal acne that doesn''t improve"],"howToUse":{"intro":"Per the Drug Facts label.","steps":["Use 1 to 2 times a day.","Wet your hands and face.","Gently massage onto the face, avoiding the eyes, and rinse thoroughly.","If dryness or irritation occurs, use it less often; if it continues, stop using it."],"sourceUrl":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5597df54-2e58-0d6a-e063-6394a90a1697","sourceLabel":"DailyMed: Mighty Cleanser Drug Facts"},"warnings":["For external use only.","Skin irritation and dryness are more likely if you use another topical acne medicine at the same time. If irritation occurs, use only one topical acne medicine at a time.","Avoid the eyes.","Keep out of reach of children. If swallowed, get medical help or contact a Poison Control Center right away."],"ingredientScience":[{"name":"Salicylic acid 2%","text":"The FDA''s OTC acne rules allow salicylic acid at 0.5% to 2%, so this is the top over-the-counter strength. The American Academy of Dermatology''s 2024 guidelines, built on a systematic review, give topical salicylic acid a conditional recommendation, weaker than the strong recommendations for benzoyl peroxide, topical retinoids and topical antibiotics. The AAD''s patient guidance lists a salicylic acid or benzoyl peroxide wash, twice a day, as a first step for red bumps.","citations":[{"url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-D/part-333/subpart-D/section-333.310","label":"FDA (21 CFR 333.310): Acne active ingredients, salicylic acid 0.5 to 2 percent"},{"url":"https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=EXT_ID:38300170%20AND%20SRC:MED&resultType=core&format=json","label":"J Am Acad Dermatol (2024): Guidelines of care for the management of acne vulgaris, abstract via Europe PMC"},{"url":"https://www.aad.org/public/diseases/acne/DIY/types-breakouts","label":"American Academy of Dermatology: How to treat different types of acne"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://herocosmetics.us/products/mighty-cleanser","text":"herocosmetics.us: Mighty Cleanser customer reviews","summary":"Hero''s own product page shows 83 reviews; no average rating was shown."}]}},"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb)
